<?php declare(strict_types=1); namespace App\Repositories; use PDO; final class LiquidityTeamRepository{public function __construct(private ?PDO $pdo=null){$this->pdo=$this->pdo??\App\Core\Database::connection();} public function create($d):int{$s=$this->pdo->prepare('INSERT INTO liquidity_teams (session_id,name,login_code,cash_balance,nft_balance) VALUES (?,?,?,?,?)');$s->execute([$d['session_id'],$d['name'],$d['login_code'],$d['cash_balance'],$d['nft_balance']]);return (int)$this->pdo->lastInsertId();} public function findById($id){$s=$this->pdo->prepare('SELECT * FROM liquidity_teams WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;} public function findByLoginCodeAndSession($c,$sid){$s=$this->pdo->prepare('SELECT * FROM liquidity_teams WHERE login_code=? AND session_id=?');$s->execute([$c,$sid]);return $s->fetch()?:null;} public function getBySessionId($sid){$s=$this->pdo->prepare('SELECT * FROM liquidity_teams WHERE session_id=? ORDER BY id');$s->execute([$sid]);return $s->fetchAll();} public function updateBalances($id,$cash,$btc,$n,$sh){$s=$this->pdo->prepare('UPDATE liquidity_teams SET cash_balance=?, btc_balance=?, nft_balance=?, pool_shares=?, updated_at=NOW() WHERE id=?');$s->execute([$cash,$btc,$n,$sh,$id]);} public function updateFinalScore($id,$score){$s=$this->pdo->prepare('UPDATE liquidity_teams SET final_score=?, updated_at=NOW() WHERE id=?');$s->execute([$score,$id]);}
public function decreaseCash($id,$amount){$this->pdo->prepare('UPDATE liquidity_teams SET cash_balance = cash_balance - ?, updated_at=NOW() WHERE id=?')->execute([$amount,$id]);}
public function increaseCash($id,$amount){$this->pdo->prepare('UPDATE liquidity_teams SET cash_balance = cash_balance + ?, updated_at=NOW() WHERE id=?')->execute([$amount,$id]);}}
